const crypto = require('crypto');

const TRACKING_PARAMS = new Set([
  'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
  'fbclid', 'gclid', 'igshid', 'ref', 'refer', 'from', 'cmpt_cd', 'sc_from'
]);

function normalizeUrl(rawUrl) {
  let s = (rawUrl || '').toString().trim();

  // 프래그먼트 제거
  const hashIdx = s.indexOf('#');
  if (hashIdx >= 0) s = s.slice(0, hashIdx);

  // 쿼리 분리
  let query = '';
  const qIdx = s.indexOf('?');
  if (qIdx >= 0) {
    query = s.slice(qIdx + 1);
    s = s.slice(0, qIdx);
  }

  // 스킴 분리 + 소문자화
  const schemeMatch = s.match(/^([a-zA-Z][a-zA-Z0-9+.\-]*):\/\//);
  let scheme = '';
  let rest = s;
  if (schemeMatch) {
    scheme = schemeMatch[1].toLowerCase();
    rest = s.slice(schemeMatch[0].length);
  }

  // 호스트/경로 분리, 호스트만 소문자화 + www 제거
  const slashIdx = rest.indexOf('/');
  let host = slashIdx >= 0 ? rest.slice(0, slashIdx) : rest;
  let path = slashIdx >= 0 ? rest.slice(slashIdx) : '';
  host = host.toLowerCase().replace(/^www\./, '');

  // 끝 슬래시 제거
  if (path.length > 1 && path.endsWith('/')) {
    path = path.slice(0, -1);
  }

  // 쿼리: 추적 파라미터만 제거, 나머지는 키 기준 정렬
  let normalizedQuery = '';
  if (query) {
    const pairs = query.split('&').filter(Boolean).map((pair) => {
      const eqIdx = pair.indexOf('=');
      const key = eqIdx >= 0 ? pair.slice(0, eqIdx) : pair;
      const value = eqIdx >= 0 ? pair.slice(eqIdx + 1) : '';
      return [key, value];
    });
    const kept = pairs.filter(([k]) => {
      let decoded = k;
      try { decoded = decodeURIComponent(k); } catch (e) {}
      return !TRACKING_PARAMS.has(decoded.toLowerCase());
    });
    kept.sort((a, b) => a[0].localeCompare(b[0]));
    normalizedQuery = kept.map(([k, v]) => (v ? `${k}=${v}` : k)).join('&');
  }

  let result = `${scheme}://${host}${path}`;
  if (normalizedQuery) result += `?${normalizedQuery}`;
  return result;
}

function sha256(text) {
  return crypto.createHash('sha256').update(text, 'utf8').digest('hex');
}

function normalizeTitleKey(title) {
  const cleaned = (title || '')
    .toLowerCase()
    .replace(/[\s\u3000]+/g, '')
    .replace(/[\[\](){}'"“”‘’.,!?…·\-–—:;]/g, '');
  return sha256(cleaned);
}

function detectSource(url) {
  if (/yna\.co\.kr/i.test(url)) return '연합뉴스';
  if (/chosun\.com/i.test(url)) return '조선일보';
  if (/mk\.co\.kr/i.test(url)) return '매일경제';
  if (/edaily\.co\.kr/i.test(url)) return '이데일리';
  return '기타';
}

function toKstString(pubDateRaw) {
  const d = new Date(pubDateRaw);
  if (isNaN(d.getTime())) return null;
  const kst = new Date(d.getTime() + 9 * 60 * 60 * 1000);
  return kst.toISOString().replace('T', ' ').slice(0, 19);
}

const results = [];
const seenTitleKeys = new Set();

for (const item of $input.all()) {
  const j = item.json;
  const rawUrl = j.link || j.url || '';
  if (!rawUrl) continue;

  const title = (j.title || '').toString().trim();
  const pubDateRaw = j.pubDate || j.isoDate || j.published_at || '';
  const source = detectSource(rawUrl);

  const snippetRaw = j.content || j.contentSnippet || j.description || title;
  const snippet = snippetRaw
    .toString()
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 1000);

  const url = normalizeUrl(rawUrl);
  const article_id = sha256(url);
  const title_key = normalizeTitleKey(title);

  if (seenTitleKeys.has(title_key)) continue;
  seenTitleKeys.add(title_key);

  results.push({
    json: { article_id, title_key, title, url, published_at: toKstString(pubDateRaw), source, snippet }
  });
}

return results;

const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 7);

const all = $input.all();

// 이력 행 판별: run_date 필드가 있으면 시트에서 읽은 이력, 없으면 오늘 수집한 기사
const isHistory = (item) => item.json.run_date !== undefined;

const historyIds = new Set(
  all
    .filter(isHistory)
    .filter((item) => {
      const d = new Date(item.json.run_date);
      return isNaN(d.getTime()) ? true : d >= cutoff;
    })
    .map((item) => item.json.article_id)
    .filter(Boolean)
);

const articles = all.filter((item) => !isHistory(item));

return articles.filter((item) => !historyIds.has(item.json.article_id));

const INCLUDE_KEYWORDS = [
  // 증시
  '코스피', '코스닥', '증시', '주가', '상장', '공모주', '배당', '시가총액', '나스닥', 'S&P',
  // 금리·통화
  '금리', '기준금리', '한국은행', '금통위', '연준', 'FOMC', '통화정책', '국채', '채권', '수익률',
  // 환율
  '환율', '원달러', '달러', '엔화', '위안화', '외환',
  // 부동산
  '부동산', '아파트값', '분양', '전세', '주택담보', '청약', 'LTV', 'DSR',
  // 기업
  '실적', '영업이익', '매출', '인수합병', 'M&A', '유상증자', '어닝', '상장폐지',
  // 정책·거시
  '물가', '소비자물가', 'CPI', 'GDP', '경기', '재정', '세제', '수출', '무역수지', '규제',
  // 금융업
  '은행', '증권', '보험', '펀드', 'ETF', '가상자산', '비트코인', '대출', '연체'
];

const EXCLUDE_KEYWORDS = [
  '연예', '아이돌', '드라마', '영화흥행', '스포츠', '야구', '축구', '골프', '날씨', '미세먼지',
  '운세', '부고', '인사이동', '신간', '레시피', '여행후기'
];

function normalize(text) {
  return (text || '').toString().toLowerCase().replace(/\s+/g, '');
}

const MAX_ARTICLES = 30;

const scored = [];
for (const item of $input.all()) {
  const j = item.json;
  const haystack = normalize(j.title) + normalize(j.snippet);

  // 제외 키워드가 하나라도 매칭되면 즉시 탈락 (포함 키워드보다 우선)
  if (EXCLUDE_KEYWORDS.some((kw) => haystack.includes(normalize(kw)))) continue;

  const matched = INCLUDE_KEYWORDS.filter((kw) => haystack.includes(normalize(kw)));
  if (matched.length === 0) continue; // 포함 키워드 0개면 탈락

  scored.push({
    json: {
      ...j,
      keyword_score: matched.length,
      matched_keywords: matched.join(', ')
    }
  });
}

scored.sort((a, b) => b.json.keyword_score - a.json.keyword_score);

if (scored.length > MAX_ARTICLES) {
  console.log(`키워드 필터 통과 ${scored.length}건 중 상위 ${MAX_ARTICLES}건만 유지, ${scored.length - MAX_ARTICLES}건 절단`);
}

return scored.slice(0, MAX_ARTICLES);

function isRobotsBlocked(url) {
  // 조선일보: 부동산 섹션 차단
  if (/chosun\.com\/economy\/realty\//i.test(url)) return true;
  // 연합뉴스: 외국어판, cp= 파라미터 (경제 피드엔 현재 해당 없지만 방어적으로 유지)
  if (/yna\.co\.kr\/view\/(AEN|AJP|ACK|AAR|ASP|AFR|AVI)/i.test(url)) return true;
  if (/[?&]cp=/i.test(url)) return true;
  return false;
}

return $input.all().map((item) => ({
  json: { ...item.json, robots_blocked: isRobotsBlocked(item.json.url) }
}));

const MIN_LEN = 200;
const MAX_LEN = 3000;

function stripTags(html) {
  return html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

function extractByContainer(html, marker, windowSize = 30000) {
  const idx = html.indexOf(marker);
  if (idx < 0) return '';
  const region = html.slice(idx, idx + windowSize);
  const matches = region.match(/<p[^>]*>[\s\S]*?<\/p>/gi) || [];
  return matches.map((p) => stripTags(p)).join(' ').trim();
}

function extractYna(html) {
  return extractByContainer(html, 'story-news');
}

function extractMk(html) {
  return extractByContainer(html, 'news_cnt_detail_wrap');
}

function extractEdaily(html) {
  const m = html.match(/<div[^>]*itemprop="articleBody"[^>]*>([\s\S]*?)<\/div>\s*<div/i);
  return m ? stripTags(m[1]) : '';
}

function extractChosun(html) {
  const start = html.indexOf('Fusion.globalContent=');
  if (start < 0) return '';
  const jsonStart = start + 'Fusion.globalContent='.length;
  let depth = 0, inStr = false, esc = false, end = -1;
  for (let p = jsonStart; p < html.length; p++) {
    const ch = html[p];
    if (esc) { esc = false; continue; }
    if (ch === '\\') { esc = true; continue; }
    if (ch === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) { end = p; break; } }
  }
  if (end < 0) return '';
  try {
    const obj = JSON.parse(html.slice(jsonStart, end + 1));
    const texts = (obj.content_elements || []).filter((e) => e.type === 'text').map((e) => e.content);
    return stripTags(texts.join(' '));
  } catch (e) {
    return '';
  }
}

function extractBody(source, html) {
  if (!html) return '';
  switch (source) {
    case '연합뉴스': return extractYna(html);
    case '매일경제': return extractMk(html);
    case '이데일리': return extractEdaily(html);
    case '조선일보': return extractChosun(html);
    default: return '';
  }
}

const results = [];
let fulltextCount = 0;
let skipCount = 0;

for (const item of $input.all()) {
  const { data, ...j } = item.json; 
  let body = '';
  let body_source = '';

  if (j.robots_blocked) {
    body_source = 'robots_skip';
    skipCount++;
  } else {
    const html = data || j.body || '';
    const extracted = extractBody(j.source, html);
    if (extracted && extracted.length >= MIN_LEN) {
      body = extracted;
      body_source = 'fulltext';
      fulltextCount++;
    }
  }

  if (!body) {
    const isTitleOnly = !j.snippet || j.snippet.trim() === (j.title || '').trim();
    body = j.snippet || j.title || '';
    if (body_source !== 'robots_skip') {
      body_source = isTitleOnly ? 'title_only' : 'rss_text';
    }
  }

  body = body.slice(0, MAX_LEN);

  results.push({
    json: {
      ...j,
      body,
      body_source,
      body_len: body.length,
      needs_review: body_source === 'title_only' ? true : (j.needs_review || false)
    }
  });
}

const denom = results.length - skipCount;
const ratio = denom > 0 ? fulltextCount / denom : 1;
if (ratio < 0.5) {
  console.log(`본문 추출률 저하: ${Math.round(ratio * 100)}% (fulltext ${fulltextCount}/${denom})`);
}

return results;

function parseModelText(raw) {
  if (!raw || typeof raw !== 'string') return null;
  let cleaned = raw.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/, '')
    .replace(/```$/, '')
    .trim();
  try {
    return JSON.parse(cleaned);
  } catch (e) {
    const start = cleaned.indexOf('{');
    const end = cleaned.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try { return JSON.parse(cleaned.slice(start, end + 1)); } catch (e2) { return null; }
    }
    return null;
  }
}

const ALLOWED_CATEGORIES = ['증시', '금리', '환율', '부동산', '기업', '정책', '기타'];

function splitSentences(text) {
  return (text || '').match(/[^.!?]*[.!?]+|[^.!?]+$/g)?.map((s) => s.trim()).filter(Boolean) || [];
}

const results = [];

for (const item of $input.all()) {
  const { text, ...j } = item.json; // 필드명이 다르면 여기만 수정
  const parsed = parseModelText(text);

  const llmFailed = !parsed || parsed.summary === undefined || parsed.importance === undefined || parsed.category === undefined;
  if (llmFailed) {
    results.push({ json: { ...j, status: 'llm_error', needs_review: true } });
    continue;
  }

  let corrected = false;

  let importance = Number(parsed.importance);
  if (!Number.isInteger(importance) || importance < 1 || importance > 5) {
    importance = 3;
    corrected = true;
  }

  let category = parsed.category;
  if (!ALLOWED_CATEGORIES.includes(category)) {
    category = '기타';
    corrected = true;
  }

  let summary = (parsed.summary || '').trim();
  if (!summary) {
    summary = j.title || '';
    corrected = true;
  } else {
    const sentences = splitSentences(summary);
    if (sentences.length > 3) {
      summary = sentences.slice(0, 3).join(' ');
      corrected = true;
    }
  }

  const needs_review = j.needs_review === true || parsed.llm_needs_review === true || corrected;

  results.push({ json: { ...j, summary, importance, category, needs_review } });
}

return results;

const ALL = $input.all();

let collected = 0, deduped = 0, financial = 0;
try { collected = $('Merge Feeds').all().length; } catch (e) {}
try { deduped = $('Filter Seen').all().length; } catch (e) {}
try { financial = $('Keyword Filter').all().length; } catch (e) {}

const sourceCounts = {};
for (const item of ALL) {
  const s = item.json.source || '기타';
  sourceCounts[s] = (sourceCounts[s] || 0) + 1;
}
const sourceLine = Object.entries(sourceCounts).map(([k, v]) => `${k} ${v}`).join(' / ') || '없음';

const nonSkipped = ALL.filter((i) => i.json.body_source !== 'robots_skip');
const fulltextCount = nonSkipped.filter((i) => i.json.body_source === 'fulltext').length;
const fulltextRatio = nonSkipped.length > 0 ? fulltextCount / nonSkipped.length : 1;

const important = ALL.filter((i) => Number(i.json.importance) >= 4);
important.sort((a, b) => {
  if (b.json.importance !== a.json.importance) return b.json.importance - a.json.importance;
  return new Date(b.json.published_at) - new Date(a.json.published_at);
});

function todayKst() {
  const now = new Date();
  const kst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
  return kst.toISOString().slice(0, 10);
}

const MAX_MESSAGE_CHARS = 1900; // 디스코드 2000자 제한에 여유

const footerLines = ['──────────────'];
footerLines.push(`수집 ${collected}건 → 신규 ${deduped}건 → 금융 ${financial}건 → 중요 ${important.length}건`);
footerLines.push(`매체: ${sourceLine}`);
if (fulltextRatio < 0.5) {
  footerLines.push(`⚠️ 본문 추출률 저하 (${Math.round(fulltextRatio * 100)}%) — 선택자 점검 필요`);
}
const footerText = footerLines.join('\n');

let bodyLines = [];
let shownCount = 0;

if (important.length > 0) {
  const headerLines = [`📈 오늘의 금융 브리핑 (${todayKst()})`, `읽을 기사 ${important.length}건`, ''];

  for (const item of important) {
    const j = item.json;
    const flag = j.needs_review ? ' ⚠️' : '';
    const articleLines = [
      `[${shownCount + 1}] ${j.category} | ${j.title}${flag}`,
      `    ${j.summary}`,
      `    🔗 ${j.url}`,
      ''
    ];

    const candidate = [...headerLines, ...bodyLines, ...articleLines].join('\n');
    const reserve = footerText.length + 100; // 생략 안내 문구 여유분

    if (candidate.length + reserve > MAX_MESSAGE_CHARS) break;

    bodyLines.push(...articleLines);
    shownCount++;
  }

  const dropped = important.length - shownCount;
  const noteLines = dropped > 0
    ? [`※ 중요 기사가 ${important.length}건이라 상위 ${shownCount}건만 표시, ${dropped}건 생략됨`, '']
    : [];

  const messageText = [...headerLines, ...bodyLines, ...noteLines, footerText].join('\n');
  const shownIds = new Set(important.slice(0, shownCount).map((i) => i.json.article_id));

  return [{
    json: {
      message_text: messageText,
      has_important: true,
      important_count: important.length,
      all_articles: ALL.map((i) => ({ ...i.json, sent_in_message: shownIds.has(i.json.article_id) }))
    }
  }];
} else {
  const headerLines = [
    `📭 오늘의 금융 브리핑 (${todayKst()})`,
    '중요 기사 없음', '',
    '오늘 수집된 기사 중 브리핑 기준(중요도 4 이상)을 넘는 기사가 없었습니다.',
    '시스템은 정상 동작했습니다.', ''
  ];
  const messageText = [...headerLines, footerText].join('\n');

  return [{
    json: {
      message_text: messageText,
      has_important: false,
      important_count: 0,
      all_articles: ALL.map((i) => ({ ...i.json, sent_in_message: false }))
    }
  }];
}

let dedupedItems = [];
try { dedupedItems = $('Filter Seen').all(); } catch (e) {}

let collected = 0;
try { collected = $('Merge Feeds').all().length; } catch (e) {}

const sourceCounts = {};
for (const item of dedupedItems) {
  const s = item.json.source || '기타';
  sourceCounts[s] = (sourceCounts[s] || 0) + 1;
}
const sourceLine = Object.entries(sourceCounts).map(([k, v]) => `${k} ${v}`).join(' / ') || '없음';

function todayKst() {
  const now = new Date();
  const kst = new Date(now.getTime() + 9 * 60 * 60 * 1000);
  return kst.toISOString().slice(0, 10);
}

const lines = [];
lines.push(`📭 오늘의 금융 브리핑 (${todayKst()})`);
lines.push('중요 기사 없음');
lines.push('');
lines.push('오늘 수집된 기사 중 금융 관련 기사가 없었습니다.');
lines.push('시스템은 정상 동작했습니다.');
lines.push('');
lines.push('──────────────');
lines.push(`수집 ${collected}건 → 신규 ${dedupedItems.length}건 → 금융 0건 → 중요 0건`);
lines.push(`매체: ${sourceLine}`);

return [{
  json: {
    message_text: lines.join('\n'),
    has_important: false,
    important_count: 0,
    all_articles: []
  }
}];

function todayKst() {
  const now = new Date();
  return new Date(now.getTime() + 9 * 60 * 60 * 1000);
}

const kst = todayKst();
const run_date = kst.toISOString().slice(0, 10);
const run_at = kst.toISOString().replace('T', ' ').slice(0, 19);
const execution_id = $execution.id;

const rows = [];

for (const item of $input.all()) {
  const articles = item.json.all_articles || [];
  for (const a of articles) {
    let status = a.status; // llm_error면 Validate 단계에서 이미 붙어있음
    if (!status) {
      status = a.sent_in_message ? 'sent' : 'not_sent';
    }

    rows.push({
      json: {
        article_id: a.article_id,
        title_key: a.title_key,
        run_date,
        run_at,
        source: a.source,
        title: a.title,
        url: a.url,
        published_at: a.published_at,
        category: a.category || '',
        importance: a.importance !== undefined ? a.importance : '',
        summary: a.summary || '',
        needs_review: !!a.needs_review,
        body_source: a.body_source || '',
        body_len: a.body_len !== undefined ? a.body_len : '',
        status,
        execution_id
      }
    });
  }
}

return rows;
